/**
 * @event
 * @name scwin.objBndList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.objBndList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "check") { if (typeof scwin.setChgBasIsuNm === 'function') { await scwin.setChgBasIsuNm(); } else { console.error('[sdd] 행 동작 미정의: scwin.setChgBasIsuNm (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.setChgBasIsuNm'); } return; }
        if (typeof scwin.detail === 'function') { scwin.detail(r["stdCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.detail (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.detail'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'objBndList.oncellclick' });
    }
};

