/**
 * @method
 * @name scwin.selectAll_2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.selectAll_2 = function () {
    /* sdd-asis-lifecycle:begin selectAll_2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let checked = $("#ipt_checkAll").attr("checked");
    if (checked === "checked") {
        checked = true;
    } else {
        checked = false;
    }
    $.each($("#SendForm").find("input[name='check']"), function(i) {
            let subChecked = $(this).attr("checked");
            if (subChecked === "checked") {
                subChecked = true;
            } else {
                subChecked = false;
            }
            if (subChecked !== checked) {
                $(this).attr("checked", checked);
            }
    });
    /* sdd-asis-lifecycle:end */
};


